{
  "findings": [
    {
      "ref": "[D522]",
      "area": "data",
      "claim": "A parent reports that the app collects personal data of 10.1 million students including email, mailing addresses, dates of birth, student records and health-related information.",
      "stance": "risk",
      "quote": "According to the FTC’s complaint, these failures led to a major data breach, which allowed a hacker to access personal data of 10.1 million students, including their email and mailing addresses, dates of birth, student records and health-related information."
    },
    {
      "ref": "[D522]",
      "area": "data",
      "claim": "A parent reports that the app fails to delete unnecessary data and retains it longer than needed.",
      "stance": "mitigation",
      "quote": "The order requires Illuminate to delete or destroy covered information within 90 days if retaining it is not reasonably necessary to provide products or services under customer contracts and is not requested by customers."
    },
    {
      "ref": "[D522]",
      "area": "data",
      "claim": "A parent reports that the app must obtain independent security assessments for 10 years after the order.",
      "stance": "mitigation",
      "quote": "Illuminate must also obtain initial and biennial assessments from an independent third-party professional for 10 years after issuance of the order."
    },
    {
      "ref": "[D522]",
      "area": "data",
      "claim": "A parent reports that the app must report breaches to the FTC within 14 days of notifying any government entity.",
      "stance": "mitigation",
      "quote": "within 14 days of notifying any federal, state or local government entity about a covered incident, Illuminate must submit a report to the commission."
    }
  ]
}
